{
  "id": "V069",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "직원의 휴직 신청 문의에 답하고 어려운 문의를 인사 담당자에게 넘기는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "조건과 서류 안내 및 규정으로 답을 확정하기 어려운 문의의 인계가 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "휴직 신청의 적용 조건과 제출 서류가 포함됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "직원 질문과 현재 게시된 사내 규정이 포함됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "질문에 맞는 조건·서류 안내와 어려운 문의의 인계가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "게시된 규정만으로 답을 확정하기 어려운 문의를 인사 담당자에게 넘기는 조건이 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능이 추가되지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "직원 문의와 인사 담당자 인계 역할이 보존됨."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "휴직 신청의 승인이나 인사시스템 정보 변경은 포함하지 않습니다.",
      "view_quote": "",
      "reason": "승인 및 인사시스템 정보 변경 제외 조건이 모든 뷰에서 누락됨."
    }
  ],
  "permission_interpretation": "승인이나 인사시스템 정보 변경은 포함되지 않으며, 뷰는 이를 수행한다고 주장하지 않음."
}
